class Doc(BaseDocTemplate):
 def __init__(self,f,**kw):
  super().__init__(f,**kw); self.addPageTemplates([PageTemplate(id='p',frames=Frame(self.leftMargin,self.bottomMargin,self.width,self.height,id='f'),onPage=self.paint)])
 def paint(self,c,d):
  if d.page>1:
   c.saveState(); c.setFont('Arial',8); c.setFillColor(MUTED); c.drawString(d.leftMargin,letter[1]-1.3*cm,'RentaSmart | Informe integrado Fases 1 a 4'); c.setStrokeColor(GRID); c.line(d.leftMargin,letter[1]-1.45*cm,letter[0]-d.rightMargin,letter[1]-1.45*cm); c.drawString(d.leftMargin,1.12*cm,'Equipo 09 | Ingeniería en Ciencia de Datos'); c.drawRightString(letter[0]-d.rightMargin,1.12*cm,str(d.page)); c.restoreState()
 def afterFlowable(self,f):
  if isinstance(f,Paragraph) and f.style.name in ('H1A','H2A'):
   lvl=0 if f.style.name=='H1A' else 1; text=f.getPlainText(); key=f'k{self.page}_{abs(hash(text))%999999}'; self.canv.bookmarkPage(key); self.canv.addOutlineEntry(text,key,level=lvl,closed=False); self.notify('TOCEntry',(lvl,text,self.page,key))
